        /// not A.M_Rows x (m &gt;= 1). The returned hierarchy must be Disposed.
        /// </summary>
        public floatAMG floatAMG(in floatBSR A, in floatMxN Bnear, in AMGOptions opts, out AMGSetupInfo info)
